CREATE TABLE dbo.decoy_jobs(id varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL PRIMARY KEY,endpoint varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES dbo.endpoints(id),revision bigint NOT NULL,payload nvarchar(max) NOT NULL,state nvarchar(32) NOT NULL,receipt nvarchar(max) NULL,observation nvarchar(max) NULL,challenge nvarchar(64) NULL,CONSTRAINT UQ_decoy_job_revision UNIQUE(endpoint,revision));
CREATE TABLE dbo.decoy_job_history(sequence bigint IDENTITY(1,1) NOT NULL PRIMARY KEY,id varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES dbo.decoy_jobs(id),kind nvarchar(64) NOT NULL,created bigint NOT NULL,actor nvarchar(450) NOT NULL,payload nvarchar(max) NOT NULL,CONSTRAINT UQ_decoy_job_history UNIQUE(id,kind));
